-- =====================================================================
-- EVALUACIÓN PROFESIONAL DE JUGADORES (extensión: no toca lo existente)
-- generación + nivel = PLANTILLA → áreas → indicadores → ejercicios → criterios 1-5
-- - eval_templates: Preescolar, 2020-2019 … 2015 nivel de desarrollo / avanzado … Porteros
--   (se liga a la categoría actual por su nombre; las categorías NO se modifican)
-- - eval_elements: indicadores de cada plantilla por área
-- - eval_exercises + eval_exercise_elements: catálogo de ejercicios con criterios 1-5
-- - player_evaluations + player_evaluation_items: cada evaluación y sus calificaciones
-- La evaluación anterior (tabla evaluations) se queda igual.
-- =====================================================================
create table if not exists academia.eval_templates (
  id            text primary key default gen_random_uuid()::text,
  name          text not null,
  generation    text,
  level         text not null default 'general',   -- general | desarrollo | avanzado | porteros | …
  level_label   text not null default 'General',
  stage         text,                               -- iniciacion | formacion | desarrollo | avanzado | perfeccionamiento | porteros
  is_goalkeeper boolean not null default false,
  category_id   uuid unique references academia.categories (id) on delete set null,
  match_name    text,                               -- nombre de la categoría con la que se liga
  sort_order    smallint not null default 0,
  active        boolean not null default true,
  created_at    timestamptz not null default now()
);

create table if not exists academia.eval_elements (
  id           text primary key default gen_random_uuid()::text,
  template_id  text not null references academia.eval_templates (id) on delete cascade,
  area         text not null check (area in ('tecnica', 'partido', 'coordinacion', 'fisico')),
  name         text not null,
  sort_order   smallint not null default 0,
  active       boolean not null default true,
  unique (template_id, area, name)
);

create table if not exists academia.eval_exercises (
  id            text primary key default gen_random_uuid()::text,
  name          text not null,
  description   text,
  objective     text,
  instructions  text,
  material      text,
  duration      text,
  repetitions   text,
  difficulty    smallint check (difficulty between 1 and 5),
  criteria      jsonb not null default '{}'::jsonb,  -- {"1": "...", ..., "5": "..."}
  observations  text,
  video_url     text,
  image_url     text,
  active        boolean not null default true,
  created_at    timestamptz not null default now()
);

create table if not exists academia.eval_exercise_elements (
  exercise_id  text not null references academia.eval_exercises (id) on delete cascade,
  element_id   text not null references academia.eval_elements (id) on delete cascade,
  primary key (exercise_id, element_id)
);

create table if not exists academia.player_evaluations (
  id            uuid primary key default gen_random_uuid(),
  student_id    uuid not null references academia.students (id) on delete cascade,
  template_id   text references academia.eval_templates (id) on delete set null,
  template_name text,
  level_label   text,
  category_id   uuid references academia.categories (id) on delete set null,
  evaluated_on  date not null default current_date,
  coach         text,
  notes         text,
  area_scores   jsonb not null default '{}'::jsonb,  -- {"tecnica": 4.2, ...}
  overall       numeric(3,2),
  created_at    timestamptz not null default now()
);
create index if not exists player_evaluations_student_idx on academia.player_evaluations (student_id, evaluated_on);

create table if not exists academia.player_evaluation_items (
  id             uuid primary key default gen_random_uuid(),
  evaluation_id  uuid not null references academia.player_evaluations (id) on delete cascade,
  area           text not null,
  element_id     text,
  element_name   text not null,
  exercise_id    text,
  exercise_name  text,
  score          smallint not null check (score between 1 and 5),
  note           text
);
create index if not exists player_evaluation_items_eval_idx on academia.player_evaluation_items (evaluation_id);

do $$
declare t text;
begin
  foreach t in array array['eval_templates', 'eval_elements', 'eval_exercises', 'eval_exercise_elements', 'player_evaluations', 'player_evaluation_items'] loop
    execute format('alter table academia.%I enable row level security', t);
    execute format('drop policy if exists %I on academia.%I', t || '_admin', t);
    execute format('create policy %I on academia.%I for all to authenticated using (academia.is_admin()) with check (academia.is_admin())', t || '_admin', t);
    execute format('drop policy if exists %I on academia.%I', t || '_open_mode', t);
    execute format('create policy %I on academia.%I for all to anon using (academia.open_mode()) with check (academia.open_mode())', t || '_open_mode', t);
    execute format('grant select, insert, update, delete on academia.%I to authenticated, anon', t);
  end loop;
end $$;

-- Bitácora
create or replace function academia.trg_act_player_evaluations() returns trigger
language plpgsql security definer set search_path = academia, public as $$
begin
  perform academia.act_log('evaluacion', 'Evaluación por áreas: ' || academia.act_student(new.student_id),
    concat_ws(' · ', new.template_name, 'Promedio ' || new.overall, 'Evaluó: ' || new.coach), '/alumnos/' || new.student_id || '?tab=evaluacion', new.student_id);
  return null;
exception when others then return null;
end $$;
drop trigger if exists act_player_evaluations on academia.player_evaluations;
create trigger act_player_evaluations after insert on academia.player_evaluations for each row execute function academia.trg_act_player_evaluations();

-- ---------------------------------------------------------------------
-- CATÁLOGO (sólo se agrega lo que falta; no pisa lo que se edite después)
-- ---------------------------------------------------------------------
update academia.eval_templates t set category_id = c.id from academia.categories c where t.category_id is null and lower(trim(c.name)) = lower(t.match_name) and not exists (select 1 from academia.eval_templates x where x.category_id = c.id);
on conflict (id) do nothing;
on conflict (id) do nothing;
on conflict do nothing;
