insert into academia.eval_exercises (id, name, description, objective, instructions, material, duration, repetitions, difficulty, criteria, observations) values
  ('ej:preescolar:tecnica:conduccion', 'Conducción entre conos', 'Conducir el balón entre conos en zigzag y regresar.', 'Que el niño se familiarice y disfrute: conducir el balón pegado al pie sin perder el control.', 'Conducir el balón entre conos en zigzag y regresar. Observar si logra conducir el balón pegado al pie sin perder el control a su ritmo, en espacio amplio y sin oposición.', 'Conos y balón', '5 min', '2 a 3 intentos', 1, '{"1": "Todavía no logra conducir el balón pegado al pie sin perder el control; necesita ayuda o demostración constante.", "2": "Logra conducir el balón pegado al pie sin perder el control de forma parcial, con errores frecuentes aun con ayuda.", "3": "Logra conducir el balón pegado al pie sin perder el control correctamente a su ritmo, en espacio amplio y sin oposición.", "4": "Logra conducir el balón pegado al pie sin perder el control con seguridad y precisión a su ritmo, en espacio amplio y sin oposición.", "5": "Domina la acción de conducir el balón pegado al pie sin perder el control; es referencia para el grupo."}'::jsonb, 'Plantilla Preescolar'),
  ('ej:preescolar:tecnica:control-de-balon', 'Recibir y detener balón', 'El profe rueda el balón y el niño lo detiene con la planta o el interior.', 'Que el niño se familiarice y disfrute: recibir el balón y dejarlo quieto cerca de su cuerpo.', 'El profe rueda el balón y el niño lo detiene con la planta o el interior. Observar si logra recibir el balón y dejarlo quieto cerca de su cuerpo a su ritmo, en espacio amplio y sin oposición.', 'Balón', '5 min', '2 a 3 intentos', 1, '{"1": "Todavía no logra recibir el balón y dejarlo quieto cerca de su cuerpo; necesita ayuda o demostración constante.", "2": "Logra recibir el balón y dejarlo quieto cerca de su cuerpo de forma parcial, con errores frecuentes aun con ayuda.", "3": "Logra recibir el balón y dejarlo quieto cerca de su cuerpo correctamente a su ritmo, en espacio amplio y sin oposición.", "4": "Logra recibir el balón y dejarlo quieto cerca de su cuerpo con seguridad y precisión a su ritmo, en espacio amplio y sin oposición.", "5": "Domina la acción de recibir el balón y dejarlo quieto cerca de su cuerpo; es referencia para el grupo."}'::jsonb, 'Plantilla Preescolar'),
  ('ej:preescolar:tecnica:pase', 'Pase corto a objetivo', 'Pasar el balón hacia conos o porterías pequeñas a distancia corta.', 'Que el niño se familiarice y disfrute: pasar el balón con dirección y fuerza adecuadas.', 'Pasar el balón hacia conos o porterías pequeñas a distancia corta. Observar si logra pasar el balón con dirección y fuerza adecuadas a su ritmo, en espacio amplio y sin oposición.', 'Balones, conos o miniporterías', '5 min', '2 a 3 intentos', 1, '{"1": "Todavía no logra pasar el balón con dirección y fuerza adecuadas; necesita ayuda o demostración constante.", "2": "Logra pasar el balón con dirección y fuerza adecuadas de forma parcial, con errores frecuentes aun con ayuda.", "3": "Logra pasar el balón con dirección y fuerza adecuadas correctamente a su ritmo, en espacio amplio y sin oposición.", "4": "Logra pasar el balón con dirección y fuerza adecuadas con seguridad y precisión a su ritmo, en espacio amplio y sin oposición.", "5": "Domina la acción de pasar el balón con dirección y fuerza adecuadas; es referencia para el grupo."}'::jsonb, 'Plantilla Preescolar'),
  ('ej:preescolar:tecnica:golpeo', 'Golpeo hacia portería', 'Golpear el balón parado o en movimiento hacia la portería.', 'Que el niño se familiarice y disfrute: golpear el balón con buena técnica y dirección.', 'Golpear el balón parado o en movimiento hacia la portería. Observar si logra golpear el balón con buena técnica y dirección a su ritmo, en espacio amplio y sin oposición.', 'Balones y portería', '5 min', '2 a 3 intentos', 1, '{"1": "Todavía no logra golpear el balón con buena técnica y dirección; necesita ayuda o demostración constante.", "2": "Logra golpear el balón con buena técnica y dirección de forma parcial, con errores frecuentes aun con ayuda.", "3": "Logra golpear el balón con buena técnica y dirección correctamente a su ritmo, en espacio amplio y sin oposición.", "4": "Logra golpear el balón con buena técnica y dirección con seguridad y precisión a su ritmo, en espacio amplio y sin oposición.", "5": "Domina la acción de golpear el balón con buena técnica y dirección; es referencia para el grupo."}'::jsonb, 'Plantilla Preescolar'),
  ('ej:preescolar:tecnica:manejo-del-balon', 'Conducción libre', 'Conducir libremente en un espacio delimitado tocando el balón con ambos pies.', 'Que el niño se familiarice y disfrute: mover el balón con distintas partes del pie.', 'Conducir libremente en un espacio delimitado tocando el balón con ambos pies. Observar si logra mover el balón con distintas partes del pie a su ritmo, en espacio amplio y sin oposición.', 'Balón y conos para delimitar', '5 min', '2 a 3 intentos', 1, '{"1": "Todavía no logra mover el balón con distintas partes del pie; necesita ayuda o demostración constante.", "2": "Logra mover el balón con distintas partes del pie de forma parcial, con errores frecuentes aun con ayuda.", "3": "Logra mover el balón con distintas partes del pie correctamente a su ritmo, en espacio amplio y sin oposición.", "4": "Logra mover el balón con distintas partes del pie con seguridad y precisión a su ritmo, en espacio amplio y sin oposición.", "5": "Domina la acción de mover el balón con distintas partes del pie; es referencia para el grupo."}'::jsonb, 'Plantilla Preescolar'),
  ('ej:preescolar:partido:participacion', 'Juego 2 vs 2', 'Juego reducido 2 vs 2 en espacio pequeño.', 'Que el niño se familiarice y disfrute: participar activamente y buscar el balón.', 'Juego reducido 2 vs 2 en espacio pequeño. Observar si logra participar activamente y buscar el balón a su ritmo, en espacio amplio y sin oposición.', 'Petos, balón y miniporterías', '5 min', '2 a 3 intentos', 1, '{"1": "Todavía no logra participar activamente y buscar el balón; necesita ayuda o demostración constante.", "2": "Logra participar activamente y buscar el balón de forma parcial, con errores frecuentes aun con ayuda.", "3": "Logra participar activamente y buscar el balón correctamente a su ritmo, en espacio amplio y sin oposición.", "4": "Logra participar activamente y buscar el balón con seguridad y precisión a su ritmo, en espacio amplio y sin oposición.", "5": "Domina la acción de participar activamente y buscar el balón; es referencia para el grupo."}'::jsonb, 'Plantilla Preescolar'),
  ('ej:preescolar:partido:atencion-al-juego', 'Juego libre', 'Juego libre con consignas sencillas del profe.', 'Que el niño se familiarice y disfrute: mantener la atención en el balón y en las indicaciones.', 'Juego libre con consignas sencillas del profe. Observar si logra mantener la atención en el balón y en las indicaciones a su ritmo, en espacio amplio y sin oposición.', 'Petos y balón', '5 min', '2 a 3 intentos', 1, '{"1": "Todavía no logra mantener la atención en el balón y en las indicaciones; necesita ayuda o demostración constante.", "2": "Logra mantener la atención en el balón y en las indicaciones de forma parcial, con errores frecuentes aun con ayuda.", "3": "Logra mantener la atención en el balón y en las indicaciones correctamente a su ritmo, en espacio amplio y sin oposición.", "4": "Logra mantener la atención en el balón y en las indicaciones con seguridad y precisión a su ritmo, en espacio amplio y sin oposición.", "5": "Domina la acción de mantener la atención en el balón y en las indicaciones; es referencia para el grupo."}'::jsonb, 'Plantilla Preescolar'),
  ('ej:preescolar:partido:ubicacion', 'Juegos con zonas', 'Juego donde cada niño debe ocupar una zona marcada.', 'Que el niño se familiarice y disfrute: ubicarse en el espacio sin amontonarse con los compañeros.', 'Juego donde cada niño debe ocupar una zona marcada. Observar si logra ubicarse en el espacio sin amontonarse con los compañeros a su ritmo, en espacio amplio y sin oposición.', 'Conos, petos y balón', '5 min', '2 a 3 intentos', 1, '{"1": "Todavía no logra ubicarse en el espacio sin amontonarse con los compañeros; necesita ayuda o demostración constante.", "2": "Logra ubicarse en el espacio sin amontonarse con los compañeros de forma parcial, con errores frecuentes aun con ayuda.", "3": "Logra ubicarse en el espacio sin amontonarse con los compañeros correctamente a su ritmo, en espacio amplio y sin oposición.", "4": "Logra ubicarse en el espacio sin amontonarse con los compañeros con seguridad y precisión a su ritmo, en espacio amplio y sin oposición.", "5": "Domina la acción de ubicarse en el espacio sin amontonarse con los compañeros; es referencia para el grupo."}'::jsonb, 'Plantilla Preescolar'),
  ('ej:preescolar:partido:juego-en-equipo', 'Buscar compañero', 'Juego en el que hay que pasar a un compañero antes de anotar.', 'Que el niño se familiarice y disfrute: jugar con sus compañeros y compartir el balón.', 'Juego en el que hay que pasar a un compañero antes de anotar. Observar si logra jugar con sus compañeros y compartir el balón a su ritmo, en espacio amplio y sin oposición.', 'Petos y balón', '5 min', '2 a 3 intentos', 1, '{"1": "Todavía no logra jugar con sus compañeros y compartir el balón; necesita ayuda o demostración constante.", "2": "Logra jugar con sus compañeros y compartir el balón de forma parcial, con errores frecuentes aun con ayuda.", "3": "Logra jugar con sus compañeros y compartir el balón correctamente a su ritmo, en espacio amplio y sin oposición.", "4": "Logra jugar con sus compañeros y compartir el balón con seguridad y precisión a su ritmo, en espacio amplio y sin oposición.", "5": "Domina la acción de jugar con sus compañeros y compartir el balón; es referencia para el grupo."}'::jsonb, 'Plantilla Preescolar'),
  ('ej:preescolar:partido:reaccion-ante-perdida-del-balon', 'Recuperación del balón', 'Juego donde al perder el balón hay que intentar recuperarlo de inmediato.', 'Que el niño se familiarice y disfrute: reaccionar rápido para recuperar el balón al perderlo.', 'Juego donde al perder el balón hay que intentar recuperarlo de inmediato. Observar si logra reaccionar rápido para recuperar el balón al perderlo a su ritmo, en espacio amplio y sin oposición.', 'Petos y balón', '5 min', '2 a 3 intentos', 1, '{"1": "Todavía no logra reaccionar rápido para recuperar el balón al perderlo; necesita ayuda o demostración constante.", "2": "Logra reaccionar rápido para recuperar el balón al perderlo de forma parcial, con errores frecuentes aun con ayuda.", "3": "Logra reaccionar rápido para recuperar el balón al perderlo correctamente a su ritmo, en espacio amplio y sin oposición.", "4": "Logra reaccionar rápido para recuperar el balón al perderlo con seguridad y precisión a su ritmo, en espacio amplio y sin oposición.", "5": "Domina la acción de reaccionar rápido para recuperar el balón al perderlo; es referencia para el grupo."}'::jsonb, 'Plantilla Preescolar'),
  ('ej:preescolar:coordinacion:equilibrio', 'Caminata sobre línea', 'Desplazarse sobre una línea o en un pie, con y sin balón.', 'Que el niño se familiarice y disfrute: mantener el equilibrio en movimiento y con el balón.', 'Desplazarse sobre una línea o en un pie, con y sin balón. Observar si logra mantener el equilibrio en movimiento y con el balón a su ritmo, en espacio amplio y sin oposición.', 'Línea marcada, conos', '5 min', '2 a 3 intentos', 1, '{"1": "Todavía no logra mantener el equilibrio en movimiento y con el balón; necesita ayuda o demostración constante.", "2": "Logra mantener el equilibrio en movimiento y con el balón de forma parcial, con errores frecuentes aun con ayuda.", "3": "Logra mantener el equilibrio en movimiento y con el balón correctamente a su ritmo, en espacio amplio y sin oposición.", "4": "Logra mantener el equilibrio en movimiento y con el balón con seguridad y precisión a su ritmo, en espacio amplio y sin oposición.", "5": "Domina la acción de mantener el equilibrio en movimiento y con el balón; es referencia para el grupo."}'::jsonb, 'Plantilla Preescolar'),
  ('ej:preescolar:coordinacion:coordinacion-pie-balon', 'Circuito de conos', 'Toques y conducción coordinada entre conos o escalera.', 'Que el niño se familiarice y disfrute: coordinar sus pies con el balón.', 'Toques y conducción coordinada entre conos o escalera. Observar si logra coordinar sus pies con el balón a su ritmo, en espacio amplio y sin oposición.', 'Conos, escalera y balón', '5 min', '2 a 3 intentos', 1, '{"1": "Todavía no logra coordinar sus pies con el balón; necesita ayuda o demostración constante.", "2": "Logra coordinar sus pies con el balón de forma parcial, con errores frecuentes aun con ayuda.", "3": "Logra coordinar sus pies con el balón correctamente a su ritmo, en espacio amplio y sin oposición.", "4": "Logra coordinar sus pies con el balón con seguridad y precisión a su ritmo, en espacio amplio y sin oposición.", "5": "Domina la acción de coordinar sus pies con el balón; es referencia para el grupo."}'::jsonb, 'Plantilla Preescolar'),
  ('ej:preescolar:coordinacion:cambios-de-direccion', 'Conducción sencilla', 'Recorrido con cambios de dirección marcados por conos.', 'Que el niño se familiarice y disfrute: cambiar de dirección rápido sin perder el equilibrio.', 'Recorrido con cambios de dirección marcados por conos. Observar si logra cambiar de dirección rápido sin perder el equilibrio a su ritmo, en espacio amplio y sin oposición.', 'Conos', '5 min', '2 a 3 intentos', 1, '{"1": "Todavía no logra cambiar de dirección rápido sin perder el equilibrio; necesita ayuda o demostración constante.", "2": "Logra cambiar de dirección rápido sin perder el equilibrio de forma parcial, con errores frecuentes aun con ayuda.", "3": "Logra cambiar de dirección rápido sin perder el equilibrio correctamente a su ritmo, en espacio amplio y sin oposición.", "4": "Logra cambiar de dirección rápido sin perder el equilibrio con seguridad y precisión a su ritmo, en espacio amplio y sin oposición.", "5": "Domina la acción de cambiar de dirección rápido sin perder el equilibrio; es referencia para el grupo."}'::jsonb, 'Plantilla Preescolar'),
  ('ej:preescolar:coordinacion:coordinacion-general', 'Circuito motor', 'Circuito de saltos, giros y desplazamientos.', 'Que el niño se familiarice y disfrute: coordinar brazos y piernas en distintos movimientos.', 'Circuito de saltos, giros y desplazamientos. Observar si logra coordinar brazos y piernas en distintos movimientos a su ritmo, en espacio amplio y sin oposición.', 'Aros, conos y vallas pequeñas', '5 min', '2 a 3 intentos', 1, '{"1": "Todavía no logra coordinar brazos y piernas en distintos movimientos; necesita ayuda o demostración constante.", "2": "Logra coordinar brazos y piernas en distintos movimientos de forma parcial, con errores frecuentes aun con ayuda.", "3": "Logra coordinar brazos y piernas en distintos movimientos correctamente a su ritmo, en espacio amplio y sin oposición.", "4": "Logra coordinar brazos y piernas en distintos movimientos con seguridad y precisión a su ritmo, en espacio amplio y sin oposición.", "5": "Domina la acción de coordinar brazos y piernas en distintos movimientos; es referencia para el grupo."}'::jsonb, 'Plantilla Preescolar'),
  ('ej:preescolar:coordinacion:reaccion', 'Reacción a estímulos visuales o sonoros', 'Salir o cambiar de acción al oír o ver una señal del profe.', 'Que el niño se familiarice y disfrute: reaccionar rápido a una señal.', 'Salir o cambiar de acción al oír o ver una señal del profe. Observar si logra reaccionar rápido a una señal a su ritmo, en espacio amplio y sin oposición.', 'Silbato, conos de colores', '5 min', '2 a 3 intentos', 1, '{"1": "Todavía no logra reaccionar rápido a una señal; necesita ayuda o demostración constante.", "2": "Logra reaccionar rápido a una señal de forma parcial, con errores frecuentes aun con ayuda.", "3": "Logra reaccionar rápido a una señal correctamente a su ritmo, en espacio amplio y sin oposición.", "4": "Logra reaccionar rápido a una señal con seguridad y precisión a su ritmo, en espacio amplio y sin oposición.", "5": "Domina la acción de reaccionar rápido a una señal; es referencia para el grupo."}'::jsonb, 'Plantilla Preescolar'),
  ('ej:preescolar:fisico:velocidad', 'Carrera corta', 'Sprint de 10-20 m con salida desde distintas posiciones.', 'Que el niño se familiarice y disfrute: correr rápido en distancias cortas.', 'Sprint de 10-20 m con salida desde distintas posiciones. Observar si logra correr rápido en distancias cortas a su ritmo, en espacio amplio y sin oposición.', 'Conos', '5 min', '2 a 3 intentos', 1, '{"1": "Todavía no logra correr rápido en distancias cortas; necesita ayuda o demostración constante.", "2": "Logra correr rápido en distancias cortas de forma parcial, con errores frecuentes aun con ayuda.", "3": "Logra correr rápido en distancias cortas correctamente a su ritmo, en espacio amplio y sin oposición.", "4": "Logra correr rápido en distancias cortas con seguridad y precisión a su ritmo, en espacio amplio y sin oposición.", "5": "Domina la acción de correr rápido en distancias cortas; es referencia para el grupo."}'::jsonb, 'Plantilla Preescolar'),
  ('ej:preescolar:fisico:agilidad', 'Circuito de agilidad', 'Circuito con escalera, conos y cambios de ritmo.', 'Que el niño se familiarice y disfrute: moverse con rapidez y soltura en espacios reducidos.', 'Circuito con escalera, conos y cambios de ritmo. Observar si logra moverse con rapidez y soltura en espacios reducidos a su ritmo, en espacio amplio y sin oposición.', 'Escalera de coordinación y conos', '5 min', '2 a 3 intentos', 1, '{"1": "Todavía no logra moverse con rapidez y soltura en espacios reducidos; necesita ayuda o demostración constante.", "2": "Logra moverse con rapidez y soltura en espacios reducidos de forma parcial, con errores frecuentes aun con ayuda.", "3": "Logra moverse con rapidez y soltura en espacios reducidos correctamente a su ritmo, en espacio amplio y sin oposición.", "4": "Logra moverse con rapidez y soltura en espacios reducidos con seguridad y precisión a su ritmo, en espacio amplio y sin oposición.", "5": "Domina la acción de moverse con rapidez y soltura en espacios reducidos; es referencia para el grupo."}'::jsonb, 'Plantilla Preescolar'),
  ('ej:preescolar:fisico:movilidad', 'Desplazamientos', 'Ejercicios de movilidad articular y desplazamientos amplios.', 'Que el niño se familiarice y disfrute: moverse con amplitud y soltura en sus articulaciones.', 'Ejercicios de movilidad articular y desplazamientos amplios. Observar si logra moverse con amplitud y soltura en sus articulaciones a su ritmo, en espacio amplio y sin oposición.', 'Conos y aros', '5 min', '2 a 3 intentos', 1, '{"1": "Todavía no logra moverse con amplitud y soltura en sus articulaciones; necesita ayuda o demostración constante.", "2": "Logra moverse con amplitud y soltura en sus articulaciones de forma parcial, con errores frecuentes aun con ayuda.", "3": "Logra moverse con amplitud y soltura en sus articulaciones correctamente a su ritmo, en espacio amplio y sin oposición.", "4": "Logra moverse con amplitud y soltura en sus articulaciones con seguridad y precisión a su ritmo, en espacio amplio y sin oposición.", "5": "Domina la acción de moverse con amplitud y soltura en sus articulaciones; es referencia para el grupo."}'::jsonb, 'Plantilla Preescolar'),
  ('ej:preescolar:fisico:desplazamiento', 'Juego activo', 'Desplazamientos variados entre conos.', 'Que el niño se familiarice y disfrute: desplazarse de distintas formas (frente, lado, atrás).', 'Desplazamientos variados entre conos. Observar si logra desplazarse de distintas formas (frente, lado, atrás) a su ritmo, en espacio amplio y sin oposición.', 'Conos', '5 min', '2 a 3 intentos', 1, '{"1": "Todavía no logra desplazarse de distintas formas (frente, lado, atrás); necesita ayuda o demostración constante.", "2": "Logra desplazarse de distintas formas (frente, lado, atrás) de forma parcial, con errores frecuentes aun con ayuda.", "3": "Logra desplazarse de distintas formas (frente, lado, atrás) correctamente a su ritmo, en espacio amplio y sin oposición.", "4": "Logra desplazarse de distintas formas (frente, lado, atrás) con seguridad y precisión a su ritmo, en espacio amplio y sin oposición.", "5": "Domina la acción de desplazarse de distintas formas (frente, lado, atrás); es referencia para el grupo."}'::jsonb, 'Plantilla Preescolar'),
